describe("StatusResponseSchema", () => {
  it("parses NotRunning run_mode", () => {
    expect(StatusResponseSchema.safeParse(statusNotRunning).success).toBe(true);
  });

  it("parses Shutdown run_mode", () => {
    expect(StatusResponseSchema.safeParse(statusShutdown).success).toBe(true);
  });

  it("parses Init run_mode as the first warmup stage", () => {
    const parsed = StatusResponseSchema.safeParse(statusInit);
    expect(parsed.success).toBe(true);
    expect(warmupProgress(parsed.data?.run_mode)?.stage).toBe("initializing");
  });

  it("parses Warmup run_mode", () => {
    const parsed = StatusResponseSchema.safeParse(statusWarmup);
    expect(parsed.success).toBe(true);
    expect(warmupProgress(parsed.data?.run_mode)?.stage).toBe(
      "waiting_for_funds",
    );
  });

  it("parses Running run_mode", () => {
    expect(StatusResponseSchema.safeParse(statusRunning).success).toBe(true);
  });

  it("parses PreparingSafe run_mode", () => {
    expect(StatusResponseSchema.safeParse(statusPreparingSafe).success).toBe(
      true,
    );
  });

  it("parses PreparingSafe run_mode with balance_recommendation", () => {
    const result = StatusResponseSchema.safeParse(
      statusPreparingSafeWithRecommendation,
    );
    expect(result.success).toBe(true);
    if (!result.success) return;
    const ps = result.data.run_mode;
    if (!isPreparingSafeRunMode(ps)) throw new Error("expected PreparingSafe");
    expect(typeof ps.node_xdai).toBe("bigint");
    expect(typeof ps.node_wxhopr).toBe("bigint");
    expect(ps.balance_recommendation).not.toBeNull();
    expect(typeof ps.balance_recommendation!.wxhopr).toBe("bigint");
    expect(typeof ps.balance_recommendation!.xdai).toBe("bigint");
    expect(ps.balance_recommendation!.topup_headroom).toBe(0n);
  });

  it("parses DeployingSafe run_mode", () => {
    expect(StatusResponseSchema.safeParse(statusDeployingSafe).success).toBe(
      true,
    );
  });

  it("parses Restarting run_mode", () => {
    expect(StatusResponseSchema.safeParse(statusRestarting).success).toBe(true);
  });

  it("parses a connection with a teardown and a ready probe", () => {
    const parsed = StatusResponseSchema.safeParse(statusConnected);
    expect(parsed.success).toBe(true);
    const connection = parsed.data?.connection;
    if (connection?.type !== "connected") throw new Error("expected connected");
    expect(connection.tunnel_ping_rtt).toBe(12);
    expect(connection.stall).toBeNull();
    expect(parsed.data?.disconnecting[0]?.phase).toBe("unregister_wg");
    expect(parsed.data?.probe?.state).toBe("ready");
    expect(parsed.data?.probe?.versions?.api).toEqual(["v1"]);
    expect(parsed.data?.probe?.load?.slots.available).toBe(10);
  });

  it("parses connecting and reconnecting with their phase", () => {
    const connecting = StatusResponseSchema.safeParse(statusConnecting);
    expect(connecting.success).toBe(true);
    expect(connecting.data?.connection).toMatchObject({
      type: "connecting",
      phase: "register_wg",
    });
    const reconnecting = StatusResponseSchema.safeParse(statusReconnecting);
    expect(reconnecting.success).toBe(true);
    expect(reconnecting.data?.connection).toMatchObject({
      type: "reconnecting",
      phase: "init",
    });
  });

  it("parses a teardown with nothing connected", () => {
    const parsed = StatusResponseSchema.safeParse(statusDisconnecting);
    expect(parsed.success).toBe(true);
    expect(parsed.data?.connection.type).toBe("disconnected");
    expect(parsed.data?.disconnecting[0]?.destination).toBe("test-exit");
  });

  it("parses a stalled tunnel", () => {
    const parsed = StatusResponseSchema.safeParse(statusConnectedStalled);
    expect(parsed.success).toBe(true);
    const connection = parsed.data?.connection;
    if (connection?.type !== "connected") throw new Error("expected connected");
    expect(connection.stall?.failed_pings).toBe(2);
    expect(connection.stall?.reconnect_at).toBe(3);
  });

  it("parses an unavailable channel maintenance with its start time", () => {
    const parsed = StatusResponseSchema.safeParse(
      statusChannelMaintenanceUnavailable,
    );
    expect(parsed.success).toBe(true);
    const runMode = parsed.data?.run_mode;
    if (!isRunningRunMode(runMode)) throw new Error("expected Running");
    expect(runMode.channel_maintenance).toEqual({
      type: "unavailable",
      since: 0,
    });
  });

  it("parses a probe session with no results yet", () => {
    const parsed = StatusResponseSchema.safeParse(statusProbeOpening);
    expect(parsed.success).toBe(true);
    expect(parsed.data?.probe?.state).toBe("opening");
    expect(parsed.data?.probe?.versions).toBe(null);
  });

  it("parses all RouteHealthState, RouteWalk and QuickProbeState variants", () => {
    const parsed = StatusResponseSchema.safeParse(statusRouteHealthVariants);
    expect(parsed.success).toBe(true);
    const health = parsed.data?.destinations.map((d) => d.route_health) ?? [];
    expect(health[0]?.walk?.type).toBe("paths");
    expect(health[0]?.quick_probe?.type).toBe("checked");
    expect(health[2]?.state.type).toBe("not_routable");
    expect(health[2]?.last_error).toBe("walk timed out");
    expect(health[5]?.quick_probe?.type).toBe("failed");
    const incompatible = health[5]?.state;
    expect(incompatible).toEqual({
      type: "unrecoverable",
      reason: { type: "incompatible_api_version", offered: ["v2"] },
    });
    const latched = health[6]?.state;
    const reason = latched?.type === "unrecoverable" ? latched.reason : null;
    expect(reason).toEqual({
      type: "cannot_open_session",
      error: "surb buffer too small",
    });
    expect(health[7]).toBe(null);
    const rechecking = health[9]?.quick_probe;
    expect(rechecking?.type).toBe("checking");
    const carried = rechecking?.type === "checking" ? rechecking.last : null;
    expect(carried?.status_rtt).toBe(42);
  });

  it("parses a reconnect reported without a phase", () => {
    const parsed = StatusResponseSchema.safeParse(statusReconnectWaiting);
    expect(parsed.success).toBe(true);
    expect(parsed.data?.connection).toMatchObject({
      type: "reconnecting",
      phase: null,
    });
  });
});

