describe("DestinationSchema geo parsing", () => {
  // Wire-shaped input, as the daemon sends it, so the parse is exercised end to end.
  const destination = (geo?: unknown) => ({
    id: "dest-1",
    meta: { name: null, description: null, other: {} },
    ...(geo === undefined ? {} : { geo }),
    address: "0x1111111111111111111111111111111111111111",
    hops: 1,
    gnosis_vpn_server: "172.30.0.1:8000",
    wireguard_server: "172.30.0.1:51820",
    source: { type: "configured" },
  });
  const parsedCode = (geo?: unknown) => {
    const result = DestinationSchema.safeParse(destination(geo));
    expect(result.success).toBe(true);
    return result.success ? result.data.geo?.country : "parse failed";
  };

  it("parses meta without location or flag", () => {
    expect(DestinationSchema.safeParse(destination()).success).toBe(true);
  });

  it("defaults the overrides an older daemon does not send", () => {
    const result = DestinationSchema.safeParse(destination());
    expect(result.success).toBe(true);
    if (!result.success) return;
    expect(result.data.overrides.configured_meta).toEqual({});
  });

  it("keeps a null or absent geo as no country", () => {
    expect(parsedCode(null)).toBeUndefined();
    expect(parsedCode()).toBeUndefined();
  });

  it("lowercases the alpha-2 code for the flag class", () => {
    expect(parsedCode({ country: "GB", source: { type: "announced_ip" } }))
      .toBe(
        "gb",
      );
  });

  it("drops a code that would not be safe in a CSS class", () => {
    expect(parsedCode({ country: "x y", source: { type: "announced_ip" } }))
      .toBeUndefined();
  });

  it("drops a subdivision code, flags are country-only", () => {
    expect(parsedCode({ country: "GB-SCT", source: { type: "announced_ip" } }))
      .toBeUndefined();
  });

  it("accepts a source this app does not know yet", () => {
    expect(parsedCode({ country: "DE", source: { type: "tunnel_egress" } }))
      .toBe(
        "de",
      );
  });
});

describe("getLogUploaderWebsiteUrl", () => {
  it("returns the URL the backend serves", async () => {
    invokeMock.mockResolvedValueOnce("https://staging.example/");
    await expect(VPNService.getLogUploaderWebsiteUrl()).resolves.toBe(
      "https://staging.example/",
    );
    expect(invokeMock).toHaveBeenCalledWith("get_log_uploader_website_url");
  });

  it("rejects a value that is not a URL", async () => {
    invokeMock.mockResolvedValueOnce("not-a-url");
    await expect(VPNService.getLogUploaderWebsiteUrl()).rejects.toThrow(
      /Log Uploader URL Error/,
    );
  });

  it("rejects when the command fails", async () => {
    invokeMock.mockRejectedValueOnce("state not managed");
    await expect(VPNService.getLogUploaderWebsiteUrl()).rejects.toThrow(
      /state not managed/,
    );
  });
});
